/**
 * Platform Info Lambda
 * 
 * Returns global platform information (NAT IP address, etc.) for admin users.
 * This endpoint is protected by:
 * 1. API Gateway authorizer (requires valid JWT)
 * 2. Role check inside this Lambda (SA, SPA_, or TA_ group required)
 */
import { SSMClient, GetParameterCommand } from '@aws-sdk/client-ssm';
// No admin-auth layer on this function: bundle the layer's helper directly (amfa-442 W3-1, D1).
import { logRequest } from '../../lambda-layers/auth-layer/nodejs/node_modules/admin-auth/log-utils.cjs';
import { parseGroupsClaim } from '../../lambda-layers/auth-layer/nodejs/node_modules/admin-auth/groups-claim.cjs';

const ssmClient = new SSMClient({ region: process.env.AWS_REGION });

// Cache SSM value in Lambda warm start
let cachedNatIp = null;

/**
 * Extract user groups from JWT Authorization header
 */
function extractGroupsFromToken(authHeader) {
  if (!authHeader) return [];

  try {
    const jwt = authHeader.replace('Bearer ', '');
    const payload = JSON.parse(
      Buffer.from(jwt.split('.')[1].replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('ascii')
    );

    return parseGroupsClaim(payload['cognito:groups']);
  } catch {
    return [];
  }
}

export const handler = async (event) => {
  logRequest(console, event);

  const corsHeaders = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'Content-Type,Authorization,X-Api-Key,X-Requested-With',
    'Access-Control-Allow-Methods': 'OPTIONS,GET',
    'Content-Type': 'application/json',
  };

  // Handle OPTIONS preflight
  const method = event.requestContext?.http?.method || event.httpMethod || 'GET';
  if (method === 'OPTIONS') {
    return { statusCode: 200, headers: corsHeaders, body: '{}' };
  }

  // Only allow GET
  if (method !== 'GET') {
    return {
      statusCode: 405,
      headers: corsHeaders,
      body: JSON.stringify({ error: 'Method not allowed' }),
    };
  }

  // Role check: SA, SPA_*, or TA_* group required
  const authHeader = event.headers?.authorization || event.headers?.Authorization;
  const groups = extractGroupsFromToken(authHeader);
  const isSA = groups.includes('SA');
  const isSPA = groups.some(g => g.startsWith('SPA_'));
  const isTA = groups.some(g => g.startsWith('TA_'));

  if (!isSA && !isSPA && !isTA) {
    return {
      statusCode: 403,
      headers: corsHeaders,
      body: JSON.stringify({ error: 'Access denied. Admin role required.' }),
    };
  }

  try {
    // Read NAT IP from SSM (with Lambda warm-start caching)
    if (!cachedNatIp) {
      const result = await ssmClient.send(new GetParameterCommand({
        Name: '/amfa/vpc/nat-eip-address',
      }));
      cachedNatIp = result.Parameter?.Value || null;
    }

    return {
      statusCode: 200,
      headers: corsHeaders,
      body: JSON.stringify({
        data: {
          natIpAddress: cachedNatIp,
        },
      }),
    };
  } catch (err) {
    console.error('Failed to fetch platform info:', err);
    return {
      statusCode: 500,
      headers: corsHeaders,
      body: JSON.stringify({ error: 'Failed to fetch platform info' }),
    };
  }
};
