/**
 * Parse the cognito:groups claim as the HTTP API JWT authorizer delivers it.
 * The authorizer stringifies the array ("[SA TA_acme]", space separated); other
 * gateways hand over the array itself or a comma form ("[SA, TA_acme]").
 * Brackets, commas and whitespace are all separators, so "SA," can never be
 * mistaken for a role name.
 * CommonJS on purpose: both layer entries export it synchronously.
 */
function parseGroupsClaim(groups) {
    if (Array.isArray(groups)) return groups.map(String).map((g) => g.trim()).filter(Boolean);
    if (typeof groups !== 'string') return [];
    return groups.split(/[\[\],\s]+/).filter(Boolean);
}

module.exports = { parseGroupsClaim };
